import{_ as t,c as o,o as a,a9 as i}from"./chunks/framework.C3PHgg-M.js";const h=JSON.parse('{"title":"Queue internals & delivery tuning","description":"Dive into lifecycle configuration, leases, retries, and DLQ observability for PURISTA queues.","frontmatter":{"title":"Queue internals & delivery tuning","description":"Dive into lifecycle configuration, leases, retries, and DLQ observability for PURISTA queues.","order":299920},"headers":[],"relativePath":"handbook/2_building_business-logic/advanced/queues.md","filePath":"handbook/2_building_business-logic/advanced/queues.md","lastUpdated":1778094759000}'),r={name:"handbook/2_building_business-logic/advanced/queues.md"};function d(s,e,n,l,c,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="queue-internals-delivery-tuning" tabindex="-1">Queue internals &amp; delivery tuning <a class="header-anchor" href="#queue-internals-delivery-tuning" aria-label="Permalink to “Queue internals &amp; delivery tuning”">​</a></h1><p>The default queue builder hides most operational knobs, but production workloads often need precise control over leases, retries, and monitoring. This chapter explains how to tune those settings and what the runtime does under the hood.</p><h2 id="lifecycle-configuration" tabindex="-1">Lifecycle configuration <a class="header-anchor" href="#lifecycle-configuration" aria-label="Permalink to “Lifecycle configuration”">​</a></h2><p>Every queue definition can override the lifecycle defaults defined in <code>defaultQueueLifecycleConfig</code>:</p><table tabindex="0"><thead><tr><th>setting</th><th style="text-align:right;">default</th><th>impact</th></tr></thead><tbody><tr><td><code>visibilityTimeoutMs</code></td><td style="text-align:right;">15 minutes</td><td>How long a leased job stays invisible before it is re-queued. Increase for long-running jobs, decrease for quick bursts.</td></tr><tr><td><code>maxLeaseExtensions</code></td><td style="text-align:right;">3</td><td>Upper bound for <code>context.job.extendLease(ms)</code> before the runtime considers the job stuck.</td></tr><tr><td><code>heartbeatIntervalMs</code></td><td style="text-align:right;">5 minutes</td><td>How often the worker auto-extends leases when <code>autoHeartbeat</code> is true. Disable auto heartbeats for jobs that manage leases manually.</td></tr><tr><td><code>retryWindowMs</code></td><td style="text-align:right;">24 hours</td><td>Rolling time window for retries. After the window elapses, the runtime stops retrying and dead-letters the job.</td></tr><tr><td><code>maxAttempts</code></td><td style="text-align:right;">10</td><td>Number of <code>nack</code> retries before a job is moved to the DLQ. You can also override per enqueue call.</td></tr><tr><td><code>retryStrategy</code></td><td style="text-align:right;"><code>{ initialDelayMs: 1s, maxDelayMs: 120s, multiplier: 2, jitterFactor: 0.25 }</code></td><td>Controls the delay that <code>context.job.retry()</code> applies when you do not specify a custom <code>delayMs</code>.</td></tr></tbody></table><p>These values are applied when you call <code>.setLifecycleConfig(...)</code> on the queue builder. The CLI prompts for overrides so you can document changes as part of the scaffolded codebase.</p><h2 id="job-context-helpers" tabindex="-1">Job context helpers <a class="header-anchor" href="#job-context-helpers" aria-label="Permalink to “Job context helpers”">​</a></h2><p>Inside a worker handler (<code>setHandler(async function (context, message) { ... })</code>), the following helpers exist:</p><ul><li><code>context.job.complete(payload?)</code>: acknowledge the lease, optionally returning a payload that can be used by HTTP status endpoints.</li><li><code>context.job.retry({ delayMs?, reason? })</code>: negative acknowledge / requeue with optional delay. Retries count toward <code>maxAttempts</code>.</li><li><code>context.job.fail(reason, fatal?)</code>: mark the job as failed. Fatal failures go straight to the DLQ; non-fatal failures follow the retry policy.</li><li><code>context.job.extendLease(ms)</code>: extend the visibility timeout proactively when a job is known to take longer.</li><li><code>context.job.moveToDeadLetter(reason?)</code>: skip retries entirely and send the job to the DLQ (useful for poison-pill scenarios).</li></ul><p>Each method emits OpenTelemetry spans/tags so you can observe queue health in tracing tools.</p><h2 id="dead-letter-queues-observability" tabindex="-1">Dead-letter queues &amp; observability <a class="header-anchor" href="#dead-letter-queues-observability" aria-label="Permalink to “Dead-letter queues &amp; observability”">​</a></h2><p>Queue bridges expose <code>metrics(queueName)</code> and, when supported, operator-grade DLQ APIs:</p><ul><li><code>pending</code>, <code>inflight</code>, <code>deadLetter</code>, <code>retries</code>, <code>oldestAgeMs</code> help you decide when to scale workers or investigate stuck jobs.</li><li>When <code>deadLetterInspectSupported</code> is true, use <code>peekDeadLetter(queueName, options?)</code> to list DLQ entries.</li><li>When <code>deadLetterReplaySupported</code> is true, use <code>redriveDeadLetter(queueName, options?)</code> to replay a bounded set of DLQ entries.</li><li>When <code>deadLetterPurgeSupported</code> is true, use <code>purgeDeadLetter(queueName)</code> to clear operator-confirmed poison messages.</li><li>Emit custom events or alerts in your worker when <code>context.job.retry()</code> hits <code>maxAttempts</code> so SREs see DLQ growth before SLAs are impacted.</li></ul><p>For runtime operators:</p><ul><li>pause workers explicitly with <code>service.pauseQueueWorkers(queueName, reason?)</code></li><li>inspect paused workers with <code>service.getQueueWorkerPauseState()</code></li><li>resume workers with <code>service.resumeQueueWorkers(queueName)</code></li></ul><h2 id="dlq-operator-workflow" tabindex="-1">DLQ operator workflow <a class="header-anchor" href="#dlq-operator-workflow" aria-label="Permalink to “DLQ operator workflow”">​</a></h2><p>Use DLQs as operator inboxes, not silent sinks:</p><ol><li>inspect entries with <code>peekDeadLetter(queueName, { limit })</code></li><li>identify poison messages by <code>x-purista-dead-letter-reason</code> and application-specific headers</li><li>replay only the entries that are now safe via <code>redriveDeadLetter(queueName, { limit })</code></li><li>purge confirmed poison batches with <code>purgeDeadLetter(queueName)</code> once the incident is closed</li></ol><p>If you need long-lived replay tooling, workflow-specific remediation, or human approval, prefer queue-backed workloads over subscription retries.</p><h2 id="health-model-integration" tabindex="-1">Health model integration <a class="header-anchor" href="#health-model-integration" aria-label="Permalink to “Health model integration”">​</a></h2><p>Queue pause state is now reflected in service health:</p><ul><li>paused queues appear under <code>ServiceHealthState.pausedQueueWorkers</code></li><li>paused subscription consumers appear under <code>ServiceHealthState.pausedSubscriptionConsumers</code></li><li>service health is <code>warn</code> while paused entries exist</li></ul><h2 id="safe-defaults" tabindex="-1">Safe defaults <a class="header-anchor" href="#safe-defaults" aria-label="Permalink to “Safe defaults”">​</a></h2><ul><li>New queues default to <code>prefetch: 1</code> and FIFO-style processing.</li><li>The runtime validates queue bridge capabilities on startup when the selected bridge advertises <code>strictStartupValidation</code>.</li><li>If you do not specify a custom queue bridge, the in-memory <code>DefaultQueueBridge</code> is suitable for local development and tests only.</li><li>Production-safe choices today are <code>RedisQueueBridge</code> and <code>NatsQueueBridge</code>; pick based on the platform your operators already run.</li></ul><h2 id="delivery-semantics" tabindex="-1">Delivery semantics <a class="header-anchor" href="#delivery-semantics" aria-label="Permalink to “Delivery semantics”">​</a></h2><p>Queues are <strong>at-least-once by design</strong>: if a worker crashes before calling <code>complete</code>, the job is re-queued. Make handlers idempotent (use idempotency keys, versioned state, or side-effect guards) to avoid duplicated work when retries happen. Combine queue lifecycles with the event bridge semantics documented in <a href="./delivery-semantics-and-reliability.html">Delivery semantics and reliability</a> for a full end-to-end picture.</p><p>For Redis specifically, PURISTA uses a <code>pending</code> list, a <code>processing</code> list, and a <code>scheduled</code> sorted set. The bridge now applies atomic recovery scripts for delayed release, lease expiry, nack/requeue, and DLQ redrive, and it recovers orphaned <code>processing</code> entries when a worker crashes between claim and lease metadata registration.</p><p>For the enterprise event-to-queue storyline, see <a href="./../../6_integrations/enterprise_interoperability/">Enterprise interoperability</a>.</p>',28)])])}const f=t(r,[["render",d]]);export{h as __pageData,f as default};
